//! A building model's information, not its geometry: every object (elements, spaces,
//! storeys, types, groups, the project) and every material with their attributes by schema
//! name, property and quantity sets (values with their units in SI), materials,
//! classification references and how objects relate (type, container, aggregate, nest,
//! group, voids and fills). IDS checks, quantity take-off and model comparison read it.
//!
//! Attribute names come from the buildingSMART EXPRESS schemas (IFC2X3, IFC4, IFC4X3),
//! as tables generated by `gen/ifc_schema.py` into `schema/`.

use std::collections::HashMap;
use std::sync::OnceLock;

use super::step::{Step, V, decode_string};
use crate::{Error, Limits, Result};

/// One schema's entities: supertype and explicit attributes (inherited first).
#[derive(Debug, Default)]
pub struct Schema {
    entities: HashMap<String, EntityDef>,
}

#[derive(Debug, Default)]
struct EntityDef {
    spelled: String,
    supertype: Option<String>,
    /// Own explicit attributes: (name, kind) with kind one of `s i r b l e x a y`.
    own: Vec<(String, u8)>,
}

impl Schema {
    fn parse(text: &str) -> Schema {
        let mut entities = HashMap::new();
        for line in text.lines() {
            let mut it = line.split(' ');
            let (Some(name), Some(sup)) = (it.next(), it.next()) else {
                continue;
            };
            let own = it
                .filter_map(|a| {
                    let (n, k) = a.split_once(':')?;
                    Some((n.to_owned(), k.bytes().next()?))
                })
                .collect();
            entities.insert(
                name.to_ascii_uppercase(),
                EntityDef {
                    spelled: name.to_owned(),
                    supertype: (sup != "-").then(|| sup.to_ascii_uppercase()),
                    own,
                },
            );
        }
        Schema { entities }
    }

    /// The entity's name as the schema spells it (`IFCWALL` → `IfcWall`).
    pub fn spelled<'a>(&'a self, class: &'a str) -> &'a str {
        self.entities
            .get(class)
            .map_or(class, |d| d.spelled.as_str())
    }

    /// The table for a file's schema (`IFC2X3`, `IFC4`, `IFC4X3_ADD2`…).
    pub fn for_name(schema: &str) -> &'static Schema {
        static S2X3: OnceLock<Schema> = OnceLock::new();
        static S4: OnceLock<Schema> = OnceLock::new();
        static S4X3: OnceLock<Schema> = OnceLock::new();
        match Version::of(schema) {
            Version::Ifc2x3 => {
                S2X3.get_or_init(|| Schema::parse(include_str!("schema/ifc2x3.txt")))
            }
            Version::Ifc4 => S4.get_or_init(|| Schema::parse(include_str!("schema/ifc4.txt"))),
            Version::Ifc4x3 => {
                S4X3.get_or_init(|| Schema::parse(include_str!("schema/ifc4x3.txt")))
            }
        }
    }

    /// Whether the schema has the entity (upper case).
    pub fn has(&self, class: &str) -> bool {
        self.entities.contains_key(class)
    }

    /// The supertype of `class`.
    pub fn supertype(&self, class: &str) -> Option<&str> {
        self.entities.get(class)?.supertype.as_deref()
    }

    /// Whether `class` is `ancestor` or one of its subtypes (both upper case).
    pub fn is_a(&self, class: &str, ancestor: &str) -> bool {
        let mut c = Some(class);
        let mut n = 0;
        while let Some(x) = c {
            if x == ancestor {
                return true;
            }
            n += 1;
            if n > 64 {
                return false;
            }
            c = self.supertype(x);
        }
        false
    }

    /// Every explicit attribute of `class` in argument order: (name, kind).
    pub fn attributes(&self, class: &str) -> Vec<(&str, u8)> {
        let mut chain = Vec::new();
        let mut c = Some(class);
        while let Some(x) = c {
            let Some(d) = self.entities.get(x) else { break };
            chain.push(d);
            if chain.len() > 64 {
                break;
            }
            c = d.supertype.as_deref();
        }
        chain
            .iter()
            .rev()
            .flat_map(|d| d.own.iter().map(|(n, k)| (n.as_str(), *k)))
            .collect()
    }

    /// The argument position of attribute `name` of `class`.
    pub fn index_of(&self, class: &str, name: &str) -> Option<usize> {
        self.attributes(class).iter().position(|(n, _)| *n == name)
    }
}

/// Schema families with their own tables.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Version {
    Ifc2x3,
    Ifc4,
    Ifc4x3,
}

impl Version {
    pub fn of(schema: &str) -> Version {
        let s = schema.to_ascii_uppercase();
        if s.starts_with("IFC2X") {
            Version::Ifc2x3
        } else if s.starts_with("IFC4X") {
            Version::Ifc4x3
        } else {
            Version::Ifc4
        }
    }

    /// The name IDS uses (`IFC2X3`, `IFC4`, `IFC4X3_ADD2`).
    pub fn ids_name(self) -> &'static str {
        match self {
            Version::Ifc2x3 => "IFC2X3",
            Version::Ifc4 => "IFC4",
            Version::Ifc4x3 => "IFC4X3_ADD2",
        }
    }
}

/// An attribute or property value as the file has it.
#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    /// `$`
    Null,
    /// `*` (derived)
    Derived,
    Str(String),
    Int(i64),
    Real(f64),
    Bool(bool),
    /// `.T.`, `.F.`, `.U.` (`None`).
    Logical(Option<bool>),
    Enum(String),
    Ref(u32),
    List(Vec<Value>),
    /// A defined type's value (`IFCLABEL('x')`): its type, upper case, and the value.
    Typed(String, Box<Value>),
    Binary(String),
}

impl Value {
    /// The value inside any defined types.
    pub fn plain(&self) -> &Value {
        match self {
            Value::Typed(_, v) => v.plain(),
            v => v,
        }
    }

    /// The outermost defined type's name, upper case.
    pub fn type_name(&self) -> Option<&str> {
        match self {
            Value::Typed(t, _) => Some(t),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self.plain() {
            Value::Str(s) | Value::Enum(s) => Some(s),
            _ => None,
        }
    }

    pub fn as_f64(&self) -> Option<f64> {
        match self.plain() {
            Value::Real(r) => Some(*r),
            Value::Int(i) => Some(*i as f64),
            _ => None,
        }
    }

    pub fn as_ref(&self) -> Option<u32> {
        match self.plain() {
            Value::Ref(r) => Some(*r),
            _ => None,
        }
    }

    pub fn refs(&self) -> Vec<u32> {
        match self.plain() {
            Value::List(l) => l.iter().filter_map(Value::as_ref).collect(),
            Value::Ref(r) => vec![*r],
            _ => Vec::new(),
        }
    }

    /// Null, an empty string or list, or an unknown logical.
    pub fn is_empty(&self) -> bool {
        match self.plain() {
            Value::Null | Value::Derived => true,
            Value::Str(s) => s.is_empty(),
            Value::List(l) => l.is_empty(),
            Value::Logical(None) => true,
            _ => false,
        }
    }

    /// The value as text for a table or list ("12.5", "TRUE", "#45").
    pub fn text(&self) -> String {
        match self.plain() {
            Value::Null | Value::Derived => String::new(),
            Value::Str(s) | Value::Enum(s) | Value::Binary(s) => s.clone(),
            Value::Int(i) => i.to_string(),
            Value::Real(r) => format!("{r}"),
            Value::Bool(b) => if *b { "TRUE" } else { "FALSE" }.to_owned(),
            Value::Logical(Some(b)) => if *b { "TRUE" } else { "FALSE" }.to_owned(),
            Value::Logical(None) => "UNKNOWN".to_owned(),
            Value::Ref(r) => format!("#{r}"),
            Value::List(l) => l.iter().map(Value::text).collect::<Vec<_>>().join(", "),
            Value::Typed(..) => String::new(),
        }
    }
}

/// How a value in the file's units becomes SI: `si = v * factor + offset`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Si {
    pub factor: f64,
    pub offset: f64,
}

impl Si {
    pub fn apply(&self, v: f64) -> f64 {
        v * self.factor + self.offset
    }
}

/// What kind of property.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PropKind {
    Single,
    Enumerated,
    List,
    Bounded,
    Table,
    /// A physical quantity (`IfcQuantityLength`…).
    Quantity,
    Reference,
    Complex,
    /// An attribute of a predefined property set.
    Predefined,
    Other,
}

/// A group of values with one unit (a table has two: defining and defined).
#[derive(Clone, Debug, PartialEq)]
pub struct Values {
    pub values: Vec<Value>,
    /// For values that have a unit (measures), how they become SI.
    pub si: Option<Si>,
}

/// One property or quantity.
#[derive(Clone, Debug, PartialEq)]
pub struct Property {
    pub name: String,
    pub kind: PropKind,
    /// The value's defined type, upper case (`IFCLABEL`, `IFCLENGTHMEASURE`).
    pub data_type: Option<String>,
    pub groups: Vec<Values>,
}

impl Property {
    /// Every value, plain, in SI where it has a unit.
    pub fn si_values(&self) -> Vec<Value> {
        let mut out = Vec::new();
        for g in &self.groups {
            for v in &g.values {
                let p = v.plain().clone();
                out.push(match (g.si, &p) {
                    (Some(si), Value::Real(r)) => Value::Real(si.apply(*r)),
                    (Some(si), Value::Int(i)) if si.factor != 1.0 || si.offset != 0.0 => {
                        Value::Real(si.apply(*i as f64))
                    }
                    _ => p,
                });
            }
        }
        out
    }

    /// The values as one line of text, in the file's units.
    pub fn text(&self) -> String {
        self.groups
            .iter()
            .flat_map(|g| g.values.iter().map(Value::text))
            .collect::<Vec<_>>()
            .join(", ")
    }
}

/// What kind of set.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SetKind {
    Properties,
    Quantities,
    /// A predefined property set (`IfcDoorLiningProperties`…).
    Predefined,
    /// A material's or profile's properties.
    Material,
}

#[derive(Clone, Debug, PartialEq)]
pub struct PropertySet {
    pub id: u32,
    pub name: String,
    pub kind: SetKind,
    pub props: Vec<Property>,
}

impl PropertySet {
    pub fn get(&self, name: &str) -> Option<&Property> {
        self.props.iter().find(|p| p.name == name)
    }
}

/// A material association's target: a material, list, layer, profile or constituent set.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MaterialDef {
    pub id: u32,
    pub class: String,
    /// The set's own name (layer set name, profile or constituent set name).
    pub name: Option<String>,
    pub category: Option<String>,
    /// Each part: its own name and category, and its material's name and category.
    pub parts: Vec<[Option<String>; 4]>,
}

impl MaterialDef {
    /// Every name and category it carries (what an IDS material value matches).
    pub fn values(&self) -> Vec<&str> {
        let mut v: Vec<&str> = [&self.name, &self.category]
            .into_iter()
            .flatten()
            .map(String::as_str)
            .collect();
        for p in &self.parts {
            v.extend(p.iter().flatten().map(String::as_str));
        }
        v
    }

    /// The material names, for a list ("Concrete, Insulation").
    pub fn names(&self) -> Vec<&str> {
        let mut v: Vec<&str> = self.parts.iter().filter_map(|p| p[2].as_deref()).collect();
        if v.is_empty()
            && let Some(n) = &self.name
        {
            v.push(n);
        }
        v.dedup();
        v
    }
}

/// A classification reference and the chain above it.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ClassRef {
    pub id: u32,
    /// `Identification` (IFC4) or `ItemReference` (IFC2X3) of this reference and every
    /// reference above it, this one first.
    pub codes: Vec<String>,
    pub name: Option<String>,
    /// The classification's name (the system), when the chain reaches one.
    pub system: Option<String>,
    /// The classification itself was associated (no reference).
    pub whole_system: bool,
}

/// An object (element, space, storey, type, group, project…) or a material.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Object {
    pub id: u32,
    /// Entity type, upper case.
    pub class: String,
    pub global_id: String,
    /// Every explicit attribute by its schema name.
    pub attrs: Vec<(String, Value)>,
    /// Its type object (occurrences), or `None`.
    pub type_object: Option<u32>,
    /// Its own property and quantity sets (a type's `HasPropertySets` for types).
    pub psets: Vec<PropertySet>,
    /// Its own material association.
    pub material: Option<u32>,
    /// Its own classification associations (references or classifications).
    pub classifications: Vec<u32>,
    pub container: Option<u32>,
    pub aggregate: Option<u32>,
    pub nest: Option<u32>,
    pub groups: Vec<u32>,
    /// An opening: the element it voids.
    pub voids: Option<u32>,
    /// An element: the opening it fills.
    pub fills: Option<u32>,
}

impl Object {
    pub fn attr(&self, name: &str) -> Option<&Value> {
        self.attrs.iter().find(|(n, _)| n == name).map(|(_, v)| v)
    }

    fn attr_str(&self, name: &str) -> Option<String> {
        self.attr(name)
            .and_then(Value::as_str)
            .filter(|s| !s.is_empty())
            .map(str::to_owned)
    }

    pub fn name(&self) -> Option<String> {
        self.attr_str("Name")
    }
}

/// A model's information.
#[derive(Debug, Default)]
pub struct IfcData {
    /// The file's schema as written (`IFC4`).
    pub schema: String,
    pub version: Option<Version>,
    pub objects: Vec<Object>,
    by_id: HashMap<u32, usize>,
    by_guid: HashMap<String, usize>,
    pub materials: HashMap<u32, MaterialDef>,
    pub class_refs: HashMap<u32, ClassRef>,
    /// The project's units: unit type (`LENGTHUNIT`) → SI.
    pub units: HashMap<String, Si>,
}

impl IfcData {
    pub fn version(&self) -> Version {
        self.version.unwrap_or(Version::Ifc4)
    }

    pub fn schema_table(&self) -> &'static Schema {
        Schema::for_name(&self.schema)
    }

    pub fn get(&self, id: u32) -> Option<&Object> {
        self.by_id.get(&id).map(|&i| &self.objects[i])
    }

    pub fn by_guid(&self, guid: &str) -> Option<&Object> {
        self.by_guid.get(guid).map(|&i| &self.objects[i])
    }

    /// The object's type object, if any.
    pub fn type_of(&self, o: &Object) -> Option<&Object> {
        self.get(o.type_object?)
    }

    /// Every property set of `o` by name: its type's first (a later set of the same name
    /// replacing an earlier one), then its own, which override the type's property by
    /// property.
    pub fn psets(&self, o: &Object) -> Vec<PropertySet> {
        let mut out: Vec<PropertySet> = Vec::new();
        let is_type = self.schema_table().is_a(&o.class, "IFCTYPEOBJECT");
        let type_sets = if is_type { Some(o) } else { self.type_of(o) };
        if let Some(t) = type_sets {
            for ps in &t.psets {
                if let Some(have) = out.iter_mut().find(|x| x.name == ps.name) {
                    *have = ps.clone();
                } else {
                    out.push(ps.clone());
                }
            }
        }
        if is_type {
            return out;
        }
        for ps in &o.psets {
            if let Some(have) = out.iter_mut().find(|x| x.name == ps.name) {
                for p in &ps.props {
                    if let Some(q) = have.props.iter_mut().find(|q| q.name == p.name) {
                        *q = p.clone();
                    } else {
                        have.props.push(p.clone());
                    }
                }
                have.id = ps.id;
                have.kind = ps.kind;
            } else {
                out.push(ps.clone());
            }
        }
        out
    }

    /// The object's material: its own association, else its type's; a layer set or
    /// profile set usage stands for its set.
    pub fn material(&self, o: &Object) -> Option<&MaterialDef> {
        let id = o
            .material
            .or_else(|| self.type_of(o).and_then(|t| t.material))?;
        self.materials.get(&id)
    }

    /// The object's classification references: its own, and its type's for systems the
    /// object does not classify itself.
    pub fn classifications(&self, o: &Object) -> Vec<&ClassRef> {
        let own: Vec<&ClassRef> = o
            .classifications
            .iter()
            .filter_map(|c| self.class_refs.get(c))
            .collect();
        let mut out = own.clone();
        if let Some(t) = self.type_of(o) {
            for c in t
                .classifications
                .iter()
                .filter_map(|c| self.class_refs.get(c))
            {
                if !own.iter().any(|x| x.system == c.system) {
                    out.push(c);
                }
            }
        }
        out
    }

    /// The predefined type as IDS reads it: the type object's when it has one (its
    /// `ElementType` when user defined), else the object's own (its `ObjectType` when user
    /// defined).
    pub fn predefined_type(&self, o: &Object) -> Option<String> {
        // A type object stands for itself.
        let t = if self.schema_table().is_a(&o.class, "IFCTYPEOBJECT") {
            Some(o)
        } else {
            self.type_of(o)
        };
        if let Some(t) = t {
            let mut p = t.attr_str("PredefinedType");
            if p.is_none() || p.as_deref() == Some("USERDEFINED") {
                p = t
                    .attr_str("ElementType")
                    .or_else(|| t.attr_str("ProcessType"));
            }
            if let Some(p) = p
                && p != "NOTDEFINED"
            {
                return Some(p);
            }
        }
        let p = o.attr_str("PredefinedType");
        if p.is_none() || p.as_deref() == Some("USERDEFINED") {
            return o.attr_str("ObjectType");
        }
        p
    }

    /// Whether the predefined type is user defined (USERDEFINED with a name).
    pub fn is_user_defined(&self, o: &Object) -> bool {
        if let Some(t) = self.type_of(o)
            && t.attr_str("PredefinedType").as_deref() == Some("USERDEFINED")
        {
            return true;
        }
        o.attr_str("PredefinedType").as_deref() == Some("USERDEFINED")
    }

    /// The spatial element holding `o`: its own container, or that of the whole it is part
    /// of (an opening: of the element it voids).
    pub fn container(&self, o: &Object) -> Option<&Object> {
        let mut cur = self.get(o.id)?;
        for _ in 0..256 {
            if let Some(c) = cur.container {
                return self.get(c);
            }
            cur = self.get(cur.aggregate.or(cur.voids)?)?;
        }
        None
    }

    /// The spatial parent, whole, nest or group of `o`, for walking up the tree.
    pub fn parent(&self, o: &Object) -> Option<&Object> {
        let id = o
            .aggregate
            .or(o.nest)
            .or(o.container)
            .or(o.voids)
            .or(o.fills)
            .or_else(|| o.groups.first().copied())?;
        self.get(id)
    }

    /// The storey (or other spatial element) holding `o`, walking up wholes.
    pub fn storey(&self, o: &Object) -> Option<&Object> {
        let mut cur = self.get(o.id)?;
        for _ in 0..64 {
            if cur.id != o.id && self.schema_table().is_a(&cur.class, "IFCBUILDINGSTOREY") {
                return Some(cur);
            }
            if let Some(c) = cur.container.and_then(|c| self.get(c)) {
                let mut s = c;
                for _ in 0..64 {
                    if self.schema_table().is_a(&s.class, "IFCBUILDINGSTOREY") {
                        return Some(s);
                    }
                    match s.aggregate.and_then(|a| self.get(a)) {
                        Some(p)
                            if self.schema_table().is_a(&p.class, "IFCSPATIALELEMENT")
                                || self
                                    .schema_table()
                                    .is_a(&p.class, "IFCSPATIALSTRUCTUREELEMENT") =>
                        {
                            s = p
                        }
                        _ => break,
                    }
                }
                return Some(c);
            }
            cur = self.get(cur.aggregate.or(cur.nest).or(cur.voids).or(cur.fills)?)?;
        }
        None
    }

    /// Every object of exactly `class`.
    pub fn of_class<'a>(&'a self, class: &'a str) -> impl Iterator<Item = &'a Object> + 'a {
        self.objects.iter().filter(move |o| o.class == class)
    }
}

/// Reads the information of an IFC file (`.ifc` or `.ifczip`).
pub fn read(bytes: &[u8], limits: &Limits) -> Result<IfcData> {
    let data = super::unpack(bytes, limits)?;
    if super::is_xml(&data) {
        return Err(Error::Unsupported(
            "ifcXML is not supported; export the model as an IFC (STEP) file".into(),
        ));
    }
    let s = Step::index(&data)?;
    let schema = s
        .header_args("FILE_SCHEMA")
        .and_then(|a| a.first().and_then(|l| l.as_list()?.first()?.as_str()))
        .unwrap_or_default();
    if !schema.to_ascii_uppercase().starts_with("IFC") {
        return Err(Error::Unsupported("not an IFC model".into()));
    }
    Ok(build(&s, &schema))
}

/// A value as the schema's attribute kind wants it.
fn value(v: &V, kind: u8) -> Value {
    match v {
        V::Null => Value::Null,
        V::Star => Value::Derived,
        V::Int(i) => {
            if kind == b'r' {
                Value::Real(*i as f64)
            } else {
                Value::Int(*i)
            }
        }
        V::Real(r) => Value::Real(*r),
        V::Str(s) => Value::Str(decode_string(s)),
        V::Enum(e) => {
            let e = String::from_utf8_lossy(e).into_owned();
            match (kind, e.as_str()) {
                (b'b', "T") => Value::Bool(true),
                (b'b', "F") => Value::Bool(false),
                (b'l', "T") => Value::Logical(Some(true)),
                (b'l', "F") => Value::Logical(Some(false)),
                (b'l', "U") => Value::Logical(None),
                _ => Value::Enum(e),
            }
        }
        V::Ref(r) => Value::Ref(*r),
        V::Bin(b) => Value::Binary(String::from_utf8_lossy(b).into_owned()),
        V::List(l) => Value::List(l.iter().map(|x| value(x, 0)).collect()),
        V::Typed(t, inner) => {
            let t = String::from_utf8_lossy(t).to_ascii_uppercase();
            let k = match t.as_str() {
                "IFCBOOLEAN" => b'b',
                "IFCLOGICAL" => b'l',
                "IFCINTEGER" | "IFCCOUNTMEASURE" => b'i',
                _ if t.ends_with("MEASURE") || t == "IFCREAL" || t == "IFCNUMERICMEASURE" => b'r',
                _ => 0,
            };
            let inner = value(inner, k);
            Value::Typed(t, Box::new(inner))
        }
    }
}

/// The unit type a measure's values are in.
fn measure_unit(measure: &str) -> Option<&'static str> {
    let m = measure.strip_prefix("IFC")?.strip_suffix("MEASURE")?;
    Some(match m {
        "LENGTH" | "POSITIVELENGTH" | "NONNEGATIVELENGTH" => "LENGTHUNIT",
        "AREA" => "AREAUNIT",
        "VOLUME" => "VOLUMEUNIT",
        "MASS" => "MASSUNIT",
        "PLANEANGLE" | "POSITIVEPLANEANGLE" => "PLANEANGLEUNIT",
        "TIME" => "TIMEUNIT",
        "THERMODYNAMICTEMPERATURE" => "THERMODYNAMICTEMPERATUREUNIT",
        "ELECTRICCURRENT" => "ELECTRICCURRENTUNIT",
        "AMOUNTOFSUBSTANCE" => "AMOUNTOFSUBSTANCEUNIT",
        "LUMINOUSINTENSITY" => "LUMINOUSINTENSITYUNIT",
        "SOLIDANGLE" => "SOLIDANGLEUNIT",
        "FORCE" => "FORCEUNIT",
        "PRESSURE" => "PRESSUREUNIT",
        "ENERGY" => "ENERGYUNIT",
        "POWER" => "POWERUNIT",
        "FREQUENCY" => "FREQUENCYUNIT",
        "ELECTRICVOLTAGE" => "ELECTRICVOLTAGEUNIT",
        "ELECTRICRESISTANCE" => "ELECTRICRESISTANCEUNIT",
        "ELECTRICCAPACITANCE" => "ELECTRICCAPACITANCEUNIT",
        "ELECTRICCHARGE" => "ELECTRICCHARGEUNIT",
        "ELECTRICCONDUCTANCE" => "ELECTRICCONDUCTANCEUNIT",
        "INDUCTANCE" => "INDUCTANCEUNIT",
        "LUMINOUSFLUX" => "LUMINOUSFLUXUNIT",
        "ILLUMINANCE" => "ILLUMINANCEUNIT",
        "MAGNETICFLUX" => "MAGNETICFLUXUNIT",
        "MAGNETICFLUXDENSITY" => "MAGNETICFLUXDENSITYUNIT",
        "RADIOACTIVITY" => "RADIOACTIVITYUNIT",
        "ABSORBEDDOSE" => "ABSORBEDDOSEUNIT",
        "DOSEEQUIVALENT" => "DOSEEQUIVALENTUNIT",
        _ => return None,
    })
}

/// The quantity entities' value measures.
fn quantity_measure(class: &str) -> Option<&'static str> {
    Some(match class {
        "IFCQUANTITYLENGTH" => "IFCLENGTHMEASURE",
        "IFCQUANTITYAREA" => "IFCAREAMEASURE",
        "IFCQUANTITYVOLUME" => "IFCVOLUMEMEASURE",
        "IFCQUANTITYCOUNT" => "IFCCOUNTMEASURE",
        "IFCQUANTITYWEIGHT" => "IFCMASSMEASURE",
        "IFCQUANTITYTIME" => "IFCTIMEMEASURE",
        "IFCQUANTITYNUMBER" => "IFCNUMERICMEASURE",
        _ => return None,
    })
}

fn prefix(p: &[u8]) -> f64 {
    match p {
        b"EXA" => 1e18,
        b"PETA" => 1e15,
        b"TERA" => 1e12,
        b"GIGA" => 1e9,
        b"MEGA" => 1e6,
        b"KILO" => 1e3,
        b"HECTO" => 1e2,
        b"DECA" => 1e1,
        b"DECI" => 1e-1,
        b"CENTI" => 1e-2,
        b"MILLI" => 1e-3,
        b"MICRO" => 1e-6,
        b"NANO" => 1e-9,
        b"PICO" => 1e-12,
        b"FEMTO" => 1e-15,
        b"ATTO" => 1e-18,
        _ => 1.0,
    }
}

/// (unit type, SI) of a named unit.
fn si_unit(s: &Step, u: u32, depth: usize) -> Option<(String, Si)> {
    if depth > 6 {
        return None;
    }
    let a = s.args(u)?;
    match s.ty(u)? {
        "IFCSIUNIT" => {
            let kind = String::from_utf8_lossy(a.get(1)?.as_enum()?).into_owned();
            let p = prefix(a.get(2).and_then(V::as_enum).unwrap_or(b""));
            let name = a.get(3)?.as_enum()?;
            let (factor, offset) = match name {
                b"SQUARE_METRE" => (p * p, 0.0),
                b"CUBIC_METRE" => (p * p * p, 0.0),
                // SI's mass unit is the kilogram.
                b"GRAM" => (p * 1e-3, 0.0),
                b"DEGREE_CELSIUS" => (p, 273.15),
                _ => (p, 0.0),
            };
            Some((kind, Si { factor, offset }))
        }
        "IFCCONVERSIONBASEDUNIT" | "IFCCONVERSIONBASEDUNITWITHOFFSET" => {
            let kind = String::from_utf8_lossy(a.get(1)?.as_enum()?).into_owned();
            let mw = s.args(a.get(3)?.as_ref()?)?;
            let v = mw.first()?.as_f64()?;
            let base = mw
                .get(1)
                .and_then(V::as_ref)
                .and_then(|b| si_unit(s, b, depth + 1))
                .map_or(
                    Si {
                        factor: 1.0,
                        offset: 0.0,
                    },
                    |b| b.1,
                );
            let off = if s.ty(u)? == "IFCCONVERSIONBASEDUNITWITHOFFSET" {
                a.get(4).and_then(V::as_f64).unwrap_or(0.0)
            } else {
                0.0
            };
            Some((
                kind,
                Si {
                    factor: v * base.factor,
                    offset: off * v * base.factor + base.offset,
                },
            ))
        }
        _ => None,
    }
}

struct Builder<'s, 'a> {
    s: &'s Step<'a>,
    schema: &'static Schema,
    units: HashMap<String, Si>,
    /// Type number → class name and whether it is stored.
    kept: HashMap<u32, bool>,
}

impl Builder<'_, '_> {
    fn arg(&self, id: u32, name: &str) -> Option<V<'_>> {
        let ty = self.s.ty(id)?;
        let i = self.schema.index_of(ty, name)?;
        self.s.args(id)?.into_iter().nth(i)
    }

    fn arg_str(&self, id: u32, name: &str) -> Option<String> {
        self.arg(id, name)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
    }

    fn attrs(&self, id: u32) -> Vec<(String, Value)> {
        let Some(ty) = self.s.ty(id) else {
            return Vec::new();
        };
        let args = self.s.args(id).unwrap_or_default();
        self.schema
            .attributes(ty)
            .into_iter()
            .enumerate()
            .map(|(i, (n, k))| {
                (
                    n.to_owned(),
                    args.get(i).map_or(Value::Null, |v| value(v, k)),
                )
            })
            .collect()
    }

    fn unit_for(&self, measure: Option<&str>, own: Option<u32>) -> Option<Si> {
        if let Some(u) = own
            && let Some((_, si)) = si_unit(self.s, u, 0)
        {
            return Some(si);
        }
        let ut = measure_unit(measure?)?;
        self.units.get(ut).copied()
    }

    fn property(&self, id: u32) -> Option<Property> {
        let ty = self.s.ty(id)?.to_owned();
        let name = self.arg_str(id, "Name").unwrap_or_default();
        let a = self.s.args(id)?;
        let attr = |n: &str| -> Option<V> {
            let i = self.schema.index_of(&ty, n)?;
            a.get(i).cloned()
        };
        let unit_ref = |n: &str| attr(n).and_then(|v| v.as_ref());
        let typed = |v: &V| value(v, 0);
        let (kind, data_type, groups) = match ty.as_str() {
            "IFCPROPERTYSINGLEVALUE" => {
                let v = attr("NominalValue").map_or(Value::Null, |v| typed(&v));
                let dt = v.type_name().map(str::to_owned);
                let si = self.unit_for(dt.as_deref(), unit_ref("Unit"));
                let values = if matches!(v, Value::Null) {
                    Vec::new()
                } else {
                    vec![v]
                };
                (PropKind::Single, dt, vec![Values { values, si }])
            }
            "IFCPROPERTYENUMERATEDVALUE" => {
                let values: Vec<Value> = attr("EnumerationValues")
                    .and_then(|l| l.as_list().map(|l| l.iter().map(typed).collect()))
                    .unwrap_or_default();
                let dt = values
                    .first()
                    .and_then(|v| v.type_name())
                    .map(str::to_owned);
                (PropKind::Enumerated, dt, vec![Values { values, si: None }])
            }
            "IFCPROPERTYLISTVALUE" => {
                let values: Vec<Value> = attr("ListValues")
                    .and_then(|l| l.as_list().map(|l| l.iter().map(typed).collect()))
                    .unwrap_or_default();
                let dt = values
                    .first()
                    .and_then(|v| v.type_name())
                    .map(str::to_owned);
                let si = self.unit_for(dt.as_deref(), unit_ref("Unit"));
                (PropKind::List, dt, vec![Values { values, si }])
            }
            "IFCPROPERTYBOUNDEDVALUE" => {
                let mut values = Vec::new();
                for n in ["UpperBoundValue", "LowerBoundValue", "SetPointValue"] {
                    if let Some(v) = attr(n) {
                        let v = typed(&v);
                        if !matches!(v, Value::Null) {
                            values.push(v);
                        }
                    }
                }
                let dt = values
                    .first()
                    .and_then(|v| v.type_name())
                    .map(str::to_owned);
                let si = self.unit_for(dt.as_deref(), unit_ref("Unit"));
                (PropKind::Bounded, dt, vec![Values { values, si }])
            }
            "IFCPROPERTYTABLEVALUE" => {
                let col = |n: &str, u: &str| {
                    let values: Vec<Value> = attr(n)
                        .and_then(|l| l.as_list().map(|l| l.iter().map(typed).collect()))
                        .unwrap_or_default();
                    let dt = values
                        .first()
                        .and_then(|v| v.type_name())
                        .map(str::to_owned);
                    let si = self.unit_for(dt.as_deref(), unit_ref(u));
                    (dt, Values { values, si })
                };
                let (d1, g1) = col("DefiningValues", "DefiningUnit");
                let (d2, g2) = col("DefinedValues", "DefinedUnit");
                (PropKind::Table, d1.or(d2), vec![g1, g2])
            }
            "IFCPROPERTYREFERENCEVALUE" => (PropKind::Reference, None, Vec::new()),
            "IFCCOMPLEXPROPERTY" => (PropKind::Complex, None, Vec::new()),
            q if quantity_measure(q).is_some() => {
                let m = quantity_measure(q).map(str::to_owned);
                let v = a.get(3).map_or(Value::Null, |v| value(v, b'r'));
                let si = self.unit_for(m.as_deref(), a.get(2).and_then(|v| v.as_ref()));
                let values = if matches!(v, Value::Null) {
                    Vec::new()
                } else {
                    vec![Value::Typed(m.clone().unwrap_or_default(), Box::new(v))]
                };
                (PropKind::Quantity, m, vec![Values { values, si }])
            }
            _ => (PropKind::Other, None, Vec::new()),
        };
        Some(Property {
            name,
            kind,
            data_type,
            groups,
        })
    }

    fn pset(&self, id: u32) -> Option<PropertySet> {
        let ty = self.s.ty(id)?;
        let name = self.arg_str(id, "Name").unwrap_or_default();
        if ty == "IFCPROPERTYSET" || ty == "IFCELEMENTQUANTITY" {
            let field = if ty == "IFCPROPERTYSET" {
                "HasProperties"
            } else {
                "Quantities"
            };
            let props = unique(
                self.arg(id, field)
                    .map(|v| v.refs())
                    .unwrap_or_default()
                    .into_iter()
                    .filter_map(|p| self.property(p)),
            );
            return Some(PropertySet {
                id,
                name,
                kind: if ty == "IFCPROPERTYSET" {
                    SetKind::Properties
                } else {
                    SetKind::Quantities
                },
                props,
            });
        }
        if self.schema.is_a(ty, "IFCPREDEFINEDPROPERTYSET")
            || self.schema.is_a(ty, "IFCPROPERTYSETDEFINITION")
        {
            // Its attributes after the root's are its properties.
            let props = self
                .attrs(id)
                .into_iter()
                .skip(4)
                .filter(|(_, v)| !matches!(v.plain(), Value::Ref(_) | Value::List(_)))
                .map(|(n, v)| Property {
                    name: n,
                    kind: PropKind::Predefined,
                    data_type: None,
                    groups: vec![Values {
                        values: if matches!(v, Value::Null) {
                            Vec::new()
                        } else {
                            vec![v]
                        },
                        si: None,
                    }],
                })
                .collect();
            return Some(PropertySet {
                id,
                name: if name.is_empty() {
                    self.schema.spelled(ty).to_owned()
                } else {
                    name
                },
                kind: SetKind::Predefined,
                props,
            });
        }
        None
    }

    fn material_def(&self, id: u32) -> Option<MaterialDef> {
        let ty = self.s.ty(id)?.to_owned();
        let mname = |m: Option<u32>| m.and_then(|m| self.arg_str(m, "Name"));
        let mcat = |m: Option<u32>| m.and_then(|m| self.arg_str(m, "Category"));
        let mut d = MaterialDef {
            id,
            class: ty.clone(),
            ..MaterialDef::default()
        };
        match ty.as_str() {
            "IFCMATERIAL" => {
                d.name = self.arg_str(id, "Name");
                d.category = self.arg_str(id, "Category");
            }
            "IFCMATERIALLIST" => {
                for m in self
                    .arg(id, "Materials")
                    .map(|v| v.refs())
                    .unwrap_or_default()
                {
                    d.parts.push([None, None, mname(Some(m)), mcat(Some(m))]);
                }
            }
            "IFCMATERIALLAYERSETUSAGE"
            | "IFCMATERIALPROFILESETUSAGE"
            | "IFCMATERIALPROFILESETUSAGETAPERING" => {
                let field = if ty == "IFCMATERIALLAYERSETUSAGE" {
                    "ForLayerSet"
                } else {
                    "ForProfileSet"
                };
                let set = self.arg(id, field).and_then(|v| v.as_ref())?;
                return self.material_def(set);
            }
            "IFCMATERIALLAYERSET" => {
                d.name = self.arg_str(id, "LayerSetName");
                for l in self
                    .arg(id, "MaterialLayers")
                    .map(|v| v.refs())
                    .unwrap_or_default()
                {
                    let m = self.arg(l, "Material").and_then(|v| v.as_ref());
                    d.parts.push([
                        self.arg_str(l, "Name"),
                        self.arg_str(l, "Category"),
                        mname(m),
                        mcat(m),
                    ]);
                }
            }
            "IFCMATERIALLAYER" | "IFCMATERIALPROFILE" | "IFCMATERIALCONSTITUENT" => {
                let m = self.arg(id, "Material").and_then(|v| v.as_ref());
                d.parts.push([
                    self.arg_str(id, "Name"),
                    self.arg_str(id, "Category"),
                    mname(m),
                    mcat(m),
                ]);
            }
            "IFCMATERIALPROFILESET" | "IFCMATERIALCONSTITUENTSET" => {
                d.name = self.arg_str(id, "Name");
                let field = if ty == "IFCMATERIALPROFILESET" {
                    "MaterialProfiles"
                } else {
                    "MaterialConstituents"
                };
                for p in self.arg(id, field).map(|v| v.refs()).unwrap_or_default() {
                    let m = self.arg(p, "Material").and_then(|v| v.as_ref());
                    d.parts.push([
                        self.arg_str(p, "Name"),
                        self.arg_str(p, "Category"),
                        mname(m),
                        mcat(m),
                    ]);
                }
            }
            _ => return None,
        }
        Some(d)
    }

    fn class_ref(&self, id: u32) -> Option<ClassRef> {
        let ty = self.s.ty(id)?;
        let mut r = ClassRef {
            id,
            ..ClassRef::default()
        };
        if ty == "IFCCLASSIFICATION" {
            r.system = self.arg_str(id, "Name");
            r.whole_system = true;
            return Some(r);
        }
        if ty != "IFCCLASSIFICATIONREFERENCE" {
            return None;
        }
        r.name = self.arg_str(id, "Name");
        let mut cur = Some(id);
        let mut n = 0;
        while let Some(c) = cur {
            n += 1;
            if n > 32 {
                break;
            }
            match self.s.ty(c) {
                Some("IFCCLASSIFICATIONREFERENCE") => {
                    if let Some(code) = self
                        .arg_str(c, "Identification")
                        .or_else(|| self.arg_str(c, "ItemReference"))
                    {
                        r.codes.push(code);
                    }
                    cur = self.arg(c, "ReferencedSource").and_then(|v| v.as_ref());
                }
                Some("IFCCLASSIFICATION") => {
                    r.system = self.arg_str(c, "Name");
                    break;
                }
                _ => break,
            }
        }
        Some(r)
    }
}

/// Properties by name: a later one of the same name replaces an earlier one in its place.
fn unique(props: impl Iterator<Item = Property>) -> Vec<Property> {
    let mut out: Vec<Property> = Vec::new();
    for p in props {
        match out.iter_mut().find(|q| q.name == p.name) {
            Some(q) => *q = p,
            None => out.push(p),
        }
    }
    out
}

/// What is not kept as an object.
const SKIPPED: &[&str] = &[
    "IFCRELATIONSHIP",
    "IFCPROPERTYDEFINITION",
    "IFCPROPERTYABSTRACTION",
    "IFCPROPERTY",
    "IFCREPRESENTATIONITEM",
    "IFCREPRESENTATION",
    "IFCPRODUCTREPRESENTATION",
    "IFCREPRESENTATIONCONTEXT",
    "IFCREPRESENTATIONMAP",
    "IFCOBJECTPLACEMENT",
    "IFCPROFILEDEF",
    "IFCMATERIALPROPERTIES",
    "IFCEXTENDEDMATERIALPROPERTIES",
    "IFCMATERIALLAYERSETUSAGE",
    "IFCMATERIALPROFILESETUSAGE",
    "IFCSHAPEASPECT",
    "IFCVIRTUALGRIDINTERSECTION",
    "IFCGRIDAXIS",
];

fn build(s: &Step, schema_name: &str) -> IfcData {
    let schema = Schema::for_name(schema_name);
    let version = Version::of(schema_name);
    // Project units.
    let mut units = HashMap::new();
    let ua = s
        .of_types(&["IFCPROJECT", "IFCPROJECTLIBRARY"])
        .into_iter()
        .find_map(|p| s.args(p)?.get(8)?.as_ref())
        .or_else(|| s.of_types(&["IFCUNITASSIGNMENT"]).into_iter().next());
    if let Some(a) = ua.and_then(|u| s.args(u)) {
        for u in a.first().map(V::refs).unwrap_or_default() {
            if let Some((k, si)) = si_unit(s, u, 0) {
                units.insert(k, si);
            }
        }
    }
    let mut b = Builder {
        s,
        schema,
        units,
        kept: HashMap::new(),
    };
    // Which entity types are objects (kept) and which relations matter.
    let mut objects = Vec::new();
    let mut rels: Vec<(u32, String)> = Vec::new();
    let mut mat_props: Vec<u32> = Vec::new();
    for (id, tn) in s.all() {
        let Some(ty) = s.ty(id) else { continue };
        let keep = *b.kept.entry(tn).or_insert_with(|| {
            // Everything but geometry, relationships and what they carry (read into the
            // objects instead).
            schema.has(ty)
                && !SKIPPED.iter().any(|a| schema.is_a(ty, a))
                && !(version == Version::Ifc2x3
                    && ty.starts_with("IFCMATERIAL")
                    && ty.contains("PROPERTIES"))
        });
        if keep {
            objects.push(id);
        }
        if ty.starts_with("IFCREL") || ty == "IFCEXTERNALREFERENCERELATIONSHIP" {
            rels.push((id, ty.to_owned()));
        } else if ty == "IFCMATERIALPROPERTIES" || ty == "IFCEXTENDEDMATERIALPROPERTIES" {
            mat_props.push(id);
        }
    }
    let mut out: Vec<Object> = objects
        .iter()
        .map(|&id| {
            let attrs = b.attrs(id);
            let global_id = attrs
                .iter()
                .find(|(n, _)| n == "GlobalId")
                .and_then(|(_, v)| v.as_str())
                .unwrap_or("")
                .to_owned();
            Object {
                id,
                class: s.ty(id).unwrap_or("").to_owned(),
                global_id,
                attrs,
                ..Object::default()
            }
        })
        .collect();
    let by_id: HashMap<u32, usize> = out.iter().enumerate().map(|(i, o)| (o.id, i)).collect();
    // Type objects' own property sets.
    for o in out.iter_mut() {
        if schema.is_a(&o.class, "IFCTYPEOBJECT") {
            for p in o
                .attr("HasPropertySets")
                .map(Value::refs)
                .unwrap_or_default()
            {
                if let Some(ps) = b.pset(p) {
                    o.psets.push(ps);
                }
            }
        }
    }
    let mut materials = HashMap::new();
    let mut class_refs = HashMap::new();
    let mut psets_cache: HashMap<u32, PropertySet> = HashMap::new();
    for (id, ty) in &rels {
        let id = *id;
        let related = |n: &str| -> Vec<u32> { b.arg(id, n).map(|v| v.refs()).unwrap_or_default() };
        let one = |n: &str| b.arg(id, n).and_then(|v| v.as_ref());
        match ty.as_str() {
            "IFCRELDEFINESBYPROPERTIES" => {
                let defs: Vec<u32> = match b.arg(id, "RelatingPropertyDefinition") {
                    Some(v) => {
                        let r = v.refs();
                        if r.is_empty() {
                            v.as_ref().into_iter().collect()
                        } else {
                            r
                        }
                    }
                    None => Vec::new(),
                };
                for d in defs {
                    if !psets_cache.contains_key(&d)
                        && let Some(ps) = b.pset(d)
                    {
                        psets_cache.insert(d, ps);
                    }
                    let Some(ps) = psets_cache.get(&d) else {
                        continue;
                    };
                    for o in related("RelatedObjects") {
                        if let Some(&i) = by_id.get(&o) {
                            out[i].psets.push(ps.clone());
                        }
                    }
                }
            }
            "IFCRELDEFINESBYTYPE" => {
                let t = one("RelatingType");
                for o in related("RelatedObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].type_object = t;
                    }
                }
            }
            "IFCRELASSOCIATESMATERIAL" => {
                let Some(m) = one("RelatingMaterial") else {
                    continue;
                };
                if let std::collections::hash_map::Entry::Vacant(e) = materials.entry(m)
                    && let Some(d) = b.material_def(m)
                {
                    e.insert(d);
                }
                for o in related("RelatedObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].material = Some(m);
                    }
                }
            }
            "IFCRELASSOCIATESCLASSIFICATION" => {
                let Some(c) = one("RelatingClassification") else {
                    continue;
                };
                if let std::collections::hash_map::Entry::Vacant(e) = class_refs.entry(c)
                    && let Some(r) = b.class_ref(c)
                {
                    e.insert(r);
                }
                for o in related("RelatedObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].classifications.push(c);
                    }
                }
            }
            "IFCEXTERNALREFERENCERELATIONSHIP" => {
                let Some(c) = one("RelatingReference") else {
                    continue;
                };
                if let std::collections::hash_map::Entry::Vacant(e) = class_refs.entry(c)
                    && let Some(r) = b.class_ref(c)
                {
                    e.insert(r);
                }
                if !class_refs.contains_key(&c) {
                    continue;
                }
                for o in related("RelatedResourceObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].classifications.push(c);
                    }
                }
            }
            "IFCRELCONTAINEDINSPATIALSTRUCTURE" => {
                let c = one("RelatingStructure");
                for o in related("RelatedElements") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].container = c;
                    }
                }
            }
            "IFCRELAGGREGATES" | "IFCRELNESTS" | "IFCRELDECOMPOSES" => {
                let w = one("RelatingObject");
                for o in related("RelatedObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        if ty == "IFCRELNESTS" {
                            out[i].nest = w;
                        } else {
                            out[i].aggregate = w;
                        }
                    }
                }
            }
            "IFCRELASSIGNSTOGROUP" | "IFCRELASSIGNSTOGROUPBYFACTOR" => {
                let Some(g) = one("RelatingGroup") else {
                    continue;
                };
                for o in related("RelatedObjects") {
                    if let Some(&i) = by_id.get(&o) {
                        out[i].groups.push(g);
                    }
                }
            }
            "IFCRELVOIDSELEMENT" => {
                let (Some(e), Some(op)) =
                    (one("RelatingBuildingElement"), one("RelatedOpeningElement"))
                else {
                    continue;
                };
                if let Some(&i) = by_id.get(&op) {
                    out[i].voids = Some(e);
                }
            }
            "IFCRELFILLSELEMENT" => {
                let (Some(op), Some(e)) =
                    (one("RelatingOpeningElement"), one("RelatedBuildingElement"))
                else {
                    continue;
                };
                if let Some(&i) = by_id.get(&e) {
                    out[i].fills = Some(op);
                }
            }
            _ => {}
        }
    }
    // Material property sets go to their material.
    for mp in mat_props {
        let ty = s.ty(mp).unwrap_or("");
        let (material, field) = if ty == "IFCMATERIALPROPERTIES" {
            (b.arg(mp, "Material").and_then(|v| v.as_ref()), "Properties")
        } else {
            (
                b.arg(mp, "Material").and_then(|v| v.as_ref()),
                "ExtendedProperties",
            )
        };
        let Some(&i) = material.and_then(|m| by_id.get(&m)) else {
            continue;
        };
        let props = b
            .arg(mp, field)
            .map(|v| v.refs())
            .unwrap_or_default()
            .into_iter()
            .filter_map(|p| b.property(p))
            .collect();
        out[i].psets.push(PropertySet {
            id: mp,
            name: b.arg_str(mp, "Name").unwrap_or_default(),
            kind: SetKind::Material,
            props,
        });
    }
    // Objects' materials may not be associated with anything (IDS can name them).
    for o in &out {
        if !materials.contains_key(&o.id)
            && (o.class.starts_with("IFCMATERIAL"))
            && let Some(d) = b.material_def(o.id)
        {
            materials.insert(o.id, d);
        }
    }
    b.kept.clear();
    let by_guid = out
        .iter()
        .enumerate()
        .filter(|(_, o)| !o.global_id.is_empty())
        .map(|(i, o)| (o.global_id.clone(), i))
        .collect();
    IfcData {
        schema: schema_name.to_owned(),
        version: Some(version),
        objects: out,
        by_id,
        by_guid,
        materials,
        class_refs,
        units: b.units,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const WALL: &str = "ISO-10303-21;
HEADER;
FILE_DESCRIPTION((''),'2;1');
FILE_NAME('','',(),(),'','','');
FILE_SCHEMA(('IFC4'));
ENDSEC;
DATA;
#1=IFCPROJECT('1hqIFTRjfV6AWq_bMtnZwI',$,'P',$,$,$,$,$,#6);
#2=IFCSIUNIT(*,.LENGTHUNIT.,.MILLI.,.METRE.);
#3=IFCSIUNIT(*,.AREAUNIT.,.MILLI.,.SQUARE_METRE.);
#6=IFCUNITASSIGNMENT((#2,#3));
#7=IFCWALL('2nJrDaLQfJ1QPhdJR0o97J',$,'W1',$,$,$,$,$,.SOLIDWALL.);
#8=IFCPROPERTYSET('16MocU_IDOF8_x3Iqllz0d',$,'Pset_WallCommon',$,(#10,#11));
#9=IFCRELDEFINESBYPROPERTIES('1xdwj8qGXK4hzoNbvMdXJW',$,$,$,(#7),#8);
#10=IFCPROPERTYSINGLEVALUE('IsExternal',$,IFCBOOLEAN(.T.),$);
#11=IFCPROPERTYSINGLEVALUE('Width',$,IFCLENGTHMEASURE(200.),$);
#12=IFCWALLTYPE('3nJrDaLQfJ1QPhdJR0o97J',$,'T1',$,$,(#13),$,$,$,.USERDEFINED.);
#13=IFCPROPERTYSET('26MocU_IDOF8_x3Iqllz0d',$,'Pset_WallCommon',$,(#14));
#14=IFCPROPERTYSINGLEVALUE('FireRating',$,IFCLABEL('2HR'),$);
#15=IFCRELDEFINESBYTYPE('4xdwj8qGXK4hzoNbvMdXJW',$,$,$,(#7),#12);
#16=IFCMATERIAL('Concrete',$,'Structure');
#17=IFCRELASSOCIATESMATERIAL('5xdwj8qGXK4hzoNbvMdXJW',$,$,$,(#12),#16);
#18=IFCBUILDINGSTOREY('6xdwj8qGXK4hzoNbvMdXJW',$,'L1',$,$,$,$,$,.ELEMENT.,0.);
#19=IFCRELCONTAINEDINSPATIALSTRUCTURE('7xdwj8qGXK4hzoNbvMdXJW',$,$,$,(#7),#18);
ENDSEC;
END-ISO-10303-21;
";

    #[test]
    fn reads_attributes_properties_type_material_and_container() {
        let d = read(WALL.as_bytes(), &Limits::default()).unwrap();
        assert_eq!(d.version(), Version::Ifc4);
        let w = d.by_guid("2nJrDaLQfJ1QPhdJR0o97J").unwrap();
        assert_eq!(w.class, "IFCWALL");
        assert_eq!(w.name().as_deref(), Some("W1"));
        assert_eq!(
            w.attr("PredefinedType"),
            Some(&Value::Enum("SOLIDWALL".into()))
        );
        assert_eq!(d.predefined_type(w).as_deref(), Some("SOLIDWALL"));
        let ps = d.psets(w);
        let common = ps.iter().find(|p| p.name == "Pset_WallCommon").unwrap();
        // The occurrence's and its type's properties together.
        assert_eq!(common.props.len(), 3);
        let width = common.get("Width").unwrap();
        assert_eq!(width.data_type.as_deref(), Some("IFCLENGTHMEASURE"));
        assert_eq!(width.si_values(), vec![Value::Real(0.2)]);
        assert_eq!(
            common.get("IsExternal").unwrap().si_values(),
            vec![Value::Bool(true)]
        );
        assert_eq!(
            d.material(w).unwrap().values(),
            vec!["Concrete", "Structure"]
        );
        assert_eq!(d.storey(w).unwrap().name().as_deref(), Some("L1"));
        assert_eq!(d.units["AREAUNIT"].factor, 1e-6);
        let schema = d.schema_table();
        assert!(schema.is_a("IFCWALL", "IFCELEMENT"));
        assert_eq!(schema.index_of("IFCWALL", "PredefinedType"), Some(8));
    }
}
